"""Reproducible illustrative RU/KK exercises. Not an official or teacher-reviewed bank."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
path=ROOT/'content/demo.json'
items=[q for q in json.loads(path.read_text(encoding='utf-8')) if not q['id'].startswith('extra-')]

def add(subject,skill,topic,number,first,second):
    # Each exercise: bilingual prompt, bilingual explanation, shared/bilingual options.
    for n,lang in enumerate(['ru','kk']):
        def unpack(x):
            prompts,options,explanations=x
            opts=options[n] if isinstance(options[0],list) else options
            # Rotate by a reproducible offset; the server additionally shuffles practice.
            shift=(number+n)%len(opts)
            return dict(prompt=prompts[n],options=opts[shift:]+opts[:shift],correct_idx=(-shift)%len(opts),explanation=explanations[n])
        q=unpack(first)
        items.append(dict(q,id=f'extra-{subject}-{number}-{lang}',subject=subject,language=lang,status='demo',skill_id=skill,topic=topic[n],recheck=unpack(second)))

def numeric(subject,skill,topic,n,formula):add(subject,skill,topic,n,formula(n),formula(n+12))
for n in range(1,10):
    def percent(k):
        price=4000+1000*k; rate=[10,20,25,30,40][k%5]; correct=price*(100-rate)//100
        return ([f'Товар стоит {price} ₸. Скидка {rate}%. Сколько нужно заплатить?',f'Тауар {price} ₸ тұрады. Жеңілдік {rate}%. Қанша төлеу керек?'],list(map(str,[correct,price*rate//100,price+100,correct+500])),[f'Скидка: {price} × {rate}/100 = {price*rate//100}. Цена: {price} − {price*rate//100} = {correct} ₸.',f'Жеңілдік: {price} × {rate}/100 = {price*rate//100}. Бағасы: {price} − {price*rate//100} = {correct} ₸.'])
    numeric('math_lit','percentages',['Проценты','Пайыздар'],n,percent)
    def quadratic(k):
        a=k+1;b=k+3
        return ([f'Решите уравнение x² − {a+b}x + {a*b} = 0.',f'x² − {a+b}x + {a*b} = 0 теңдеуін шешіңіз.'],[f'{a}; {b}',f'{-a}; {-b}',f'0; {a+b}',f'1; {a*b}'],[f'(x − {a})(x − {b}) = 0. Каждый множитель может быть равен нулю: x = {a} или {b}.',f'(x − {a})(x − {b}) = 0. Әрбір көбейткіш нөлге тең болуы мүмкін: x = {a} немесе {b}.'])
    numeric('math_profile','quadratics',['Квадратные уравнения','Квадрат теңдеулер'],n,quadratic)
    def speed(k):
        v=k+2;t=k+5;dist=v*t
        return ([f'Тело прошло {dist} м за {t} с. Найдите среднюю скорость в м/с.',f'Дене {t} с ішінде {dist} м жүрді. Орташа жылдамдықты м/с-пен табыңыз.'],list(map(str,[v,dist+t,dist*t,v+1])),[f'Средняя скорость v = s/t = {dist}/{t} = {v} м/с. Не умножайте путь на время.',f'Орташа жылдамдық v = s/t = {dist}/{t} = {v} м/с. Жолды уақытқа көбейтпеңіз.'])
    numeric('physics','speed',['Средняя скорость','Орташа жылдамдық'],n,speed)
    def moles(k):
        molar=[18,44,32,28][k%4];amount=k+1;mass=molar*amount
        return ([f'Молярная масса вещества {molar} г/моль. Сколько моль в {mass} г вещества?',f'Заттың молярлық массасы {molar} г/моль. {mass} г затта неше моль бар?'],list(map(str,[amount,mass+molar,mass*molar,amount+1])),[f'n = m/M = {mass}/{molar} = {amount} моль. Массу делим на молярную массу.',f'n = m/M = {mass}/{molar} = {amount} моль. Массаны молярлық массаға бөлеміз.'])
    numeric('chemistry','moles',['Количество вещества','Зат мөлшері'],n,moles)
    def binary(k):
        val=k+7;bits=format(val,'b');terms=' + '.join(str(2**i) for i in range(len(bits)-1,-1,-1) if val&(1<<i))
        return ([f'Переведите двоичное число {bits} в десятичную систему.',f'{bits} екілік санын ондық жүйеге ауыстырыңыз.'],list(map(str,[val,val+1,val-1,val*2])),[f'Сложите веса разрядов, в которых стоит 1: {terms} = {val}.',f'1 тұрған разрядтардың салмақтарын қосыңыз: {terms} = {val}.'])
    numeric('informatics','binary',['Двоичная система','Екілік жүйе'],n,binary)

